// ---------------------------------------------------------------
// Clasifica cada correo mediante reglas explicables (sin IA).
// Categorías: importante | tarea | notificacion | newsletter | otros
// Funciona con la salida simplificada del Gmail Trigger
// (campos From, Subject, snippet, id).
// ---------------------------------------------------------------
const normalizar = (t) => String(t || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase();

const config = $('Configuración').first().json;
const remitentesImportantes = String(config.remitentesImportantes || '')
  .split(',').map((r) => normalizar(r).trim()).filter(Boolean);

const REGLAS = {
  newsletter: ['newsletter', 'boletin', 'darte de baja', 'darse de baja', 'unsubscribe', 'cancelar suscripcion', 'resumen semanal', 'digest'],
  notificacionRemitente: ['no-reply', 'noreply', 'no_reply', 'notifications', 'notificaciones', 'alerts', 'alertas', 'mailer-daemon'],
  notificacionAsunto: ['notificacion', 'alerta', 'confirmacion', 'tu pedido', 'recibo', 'inicio de sesion', 'codigo de verificacion', 'verification code', 'password reset'],
  importante: ['urgente', 'importante', 'asap', 'fecha limite', 'vence hoy', 'vencimiento', 'accion requerida', 'action required'],
  tarea: ['por favor', 'podrias', 'puedes', 'necesito que', 'pendiente', 'revisar', 'revision', 'enviar antes', 'to do', 'tarea', 'solicitud'],
};

const contiene = (texto, palabras) => palabras.find((p) => texto.includes(p));

function extraerDireccion(remitente) {
  const coincidencia = String(remitente || '').match(/<([^>]+)>/);
  return normalizar(coincidencia ? coincidencia[1] : remitente).trim();
}

function clasificar(correo) {
  const remitente = correo.From || correo.from?.text || correo.from || '';
  const direccion = extraerDireccion(remitente);
  const asunto = correo.Subject || correo.subject || '';
  const texto = normalizar(`${asunto} ${correo.snippet || correo.text || ''}`);

  let categoria = 'otros';
  let motivo = 'No coincide con ninguna regla';
  let palabra;

  if (remitentesImportantes.some((r) => direccion.includes(r))) {
    categoria = 'importante'; motivo = 'Remitente marcado como importante';
  } else if ((palabra = contiene(texto, REGLAS.newsletter))) {
    categoria = 'newsletter'; motivo = `Contiene "${palabra}"`;
  } else if ((palabra = contiene(direccion, REGLAS.notificacionRemitente))) {
    categoria = 'notificacion'; motivo = `Remitente automático (${palabra})`;
  } else if ((palabra = contiene(texto, REGLAS.importante))) {
    categoria = 'importante'; motivo = `Contiene "${palabra}"`;
  } else if ((palabra = contiene(texto, REGLAS.notificacionAsunto))) {
    categoria = 'notificacion'; motivo = `Contiene "${palabra}"`;
  } else if ((palabra = contiene(texto, REGLAS.tarea))) {
    categoria = 'tarea'; motivo = `Contiene "${palabra}"`;
  }

  return {
    message_id: correo.id || '',
    fecha_procesado: $now.toFormat('yyyy-MM-dd HH:mm'),
    remitente: direccion,
    asunto: String(asunto).slice(0, 200),
    categoria,
    motivo,
  };
}

return $input.all()
  .filter((item) => item.json && (item.json.id || item.json.Subject || item.json.subject))
  .map((item) => ({ json: clasificar(item.json) }));
